import sys

data = sys.stdin.read().split()
n = int(data[0])

neg = zero = pos = 0
for tok in data[1:1 + n]:
    x = int(tok)
    if x > 0:
        pos += 1
    elif x < 0:
        neg += 1
    else:
        zero += 1

print(neg, zero, pos)

