基-31.solution:
import math

m, n = map(int, input().split())

cnt = 0
for i in range(m, n + 1):
    if i < 2:
        continue
    is_prime = True
    for j in range(2, math.isqrt(i) + 1):
        if i % j == 0:
            is_prime = False
            break
    if is_prime:
        cnt += 1

print(cnt)

基-34.solution:
import sys

parts = sys.stdin.read().split()
a = int(parts[0])
op = parts[1]
b = int(parts[2])

if op == '+':
    print(a + b)
elif op == '-':
    print(a - b)
elif op == '*':
    print(a * b)
elif op == '/':
    if b == 0:
        print("error")
    else:
        print(f"{a / b:.2f}")
else:
    print("error")
